// ---------------------------------------------------------------------------
// Wire handlers via expressHandler
//
// Note: instance-admin routes keep an Express assertInstanceAdmin() middleware
// inline so the richer req.actor.isInstanceAdmin check is honoured.
// ---------------------------------------------------------------------------

router.get("/adapters", expressHandler(listAdapters, adapterDeps));

router.post("/adapters/install", (req, _res, next) => {
  try { assertInstanceAdmin(req); next(); } catch (err) { next(err); }
}, expressHandler(installAdapter, adapterDeps));

router.patch("/adapters/:type", (req, _res, next) => {
  try { assertInstanceAdmin(req); next(); } catch (err) { next(err); }
}, expressHandler(patchAdapter, adapterDeps));

router.patch("/adapters/:type/override", (req, _res, next) => {
  try { assertInstanceAdmin(req); next(); } catch (err) { next(err); }
}, expressHandler(patchAdapterOverride, adapterDeps));

router.delete("/adapters/:type", (req, _res, next) => {
  try { assertInstanceAdmin(req); next(); } catch (err) { next(err); }
}, expressHandler(deleteAdapter, adapterDeps));

router.post("/adapters/:type/reload", (req, _res, next) => {
  try { assertInstanceAdmin(req); next(); } catch (err) { next(err); }
}, expressHandler(reloadAdapter, adapterDeps));

router.post("/adapters/:type/reinstall", (req, _res, next) => {
  try { assertInstanceAdmin(req); next(); } catch (err) { next(err); }
}, expressHandler(reinstallAdapter, adapterDeps));

router.get("/adapters/:type/config-schema", expressHandler(getAdapterConfigSchema, adapterDeps));
router.get("/adapters/:type/ui-parser.js", expressHandler(getAdapterUiParser, adapterDeps));
